            // session without exposing the bearer in a URL, fragment, or fetch.
            const form = document.createElement("form");
            form.method = "post";
            form.action = result.url;
            const input = document.createElement("input");
            input.type = "hidden";
            input.name = "handoff_token";
            input.value = handoffToken;
